public edit Description255 tableOverride(boolean _set, Description255 _tableName)
{
    Description255 tblName;

    if (_set)
    {
        if (strScan(_tableName,'.',1,strLen(_tableName)))
        {
            this.ClassOverrideID = className2Id(subStr(_tableName,1,strScan(_tableName,'.',1,strLen(_tableName))-1));
            this.ClassOverrideMethod = subStr(_tableName,strScan(_tableName,'.',1,strLen(_tableName))+1,strLen(_tableName));
        }
        else
        {
            this.ClassOverrideID = className2Id(_tableName);
        }
    }
    tblName = TFMDisplayLineOverride::classId2Attribute(this.ClassOverrideID);
    if (!tblName)
    {
        tblName = classId2Name(this.ClassOverrideID)+ '.' + this.ClassOverrideMethod;
    }
    return tblName;
}

public display ClassName getClassName()
{

    return classId2Name(this.ClassOverrideID);
}

/// <summary>
/// Method to convert user setup registration collectors to registation Collector map, used to created registration collectors for the device.
/// </summary>
public static Map addToCollectors(Map _collectors, ClassId _orderClass, MethodName _methodName, boolean _headers = true, Map _additionalValues = new Map(Types::String, Types::String))
{
    MobPostOrderPromptOverride              override;
    Map                                     overridesSet = MobPostOrderPromptOverride::FindAll(_orderClass, _methodName);
    MobPostOrderPromptOverrideLines         lines;        
    Map                                     newCollectors = _collectors;
    MapEnumerator                           mEnum           = overridesSet.getEnumerator();
    if (!overridesSet.elements())
    {
        return _collectors;
    }
    while (mEnum.moveNext())
    {
        override = mEnum.currentValue();
        while select lines where lines.MobPostOrderPromptOverrideRecID == override.RecId && ((_headers && lines.HeadingLine == HeadingLine::Heading) || (!_headers && lines.HeadingLine == HeadingLine::Line)) && override.Active
        {
            newCollectors.Insert(lines.Name, lines.getCollectorMap());
        }
    }
    return newCollectors;
}

public void addParms()
{

    MobPostOrderMethodParms     parms;
    SysDictMethod               method = new SysDictMethod(UtilElementType::ClassStaticMethod,className2Id(this.CallclassName),this.CallMethodName);
    int                         i;
    RecordInsertList            list = new  RecordInsertList(tableNum(MobPostOrderMethodParms));

    delete_from parms where parms.PostOrderPromptOverrideRecID == this.RecId;
    if (!className2Id(this.CallclassName) || !this.CallMethodName)
    {
        return;
    }
    for (i = 1; i <= method.parameterCnt(); i++)
    {
        parms.ParmName = method.parameterName(i);
        parms.baseType = method.parameterType(i);
        parms.EDTName  = method.parameterTypeName(i);
        parms.PostOrderPromptOverrideRecID  = this.RecID;
        if (parms.baseType == Types::UserType && parms.EDTName)
        {
            parms.baseType = new DictType(extendedTypeName2Id(parms.EDTName)).baseType();
        }

        list.add(parms);
    }

    list.insertDatabase();
}

public static MobPostOrderPromptOverride Find(ClassId _orderClass, MethodName _methodName, boolean _selectForUpdate = true)
{
    MobPostOrderPromptOverride override;
    MethodName methodName= _methodName;

    override.selectForUpdate ( _selectForUpdate);

    select firstonly override where override.ClassOverrideID == _orderClass && override.ClassOverrideMethod == methodName;

    if (!override)
    {
        //Test if collector method has been passed, and find corresponding Post Method.
        methodName = TFMDocumentHandler::FindCorrespondingPostMethod(_orderClass,methodName);
        select firstonly override where override.ClassOverrideID == _orderClass && override.ClassOverrideMethod == methodName;
    }

    return override;
}

/// <summary>
/// A Find method to find multiple records, returned as a map.
/// </summary>
/// <param name = "_orderClass">The class Id of the document to find for override</param>
/// <param name = "_methodName">The method name of the document to find for override</param>
/// <param name = "_selectForUpdate">boolean, true if records should be selected for update</param>
/// <returns>A Map with the resulting records</returns>
public static Map FindAll(ClassId _orderClass, MethodName _methodName, boolean _selectForUpdate = true)
{
    MobPostOrderPromptOverride  override;
    MethodName                  methodName= _methodName;
    Map                         resultSet = new Map (Types::Int64, Types::Record);        

    override.selectForUpdate ( _selectForUpdate);

    while select override where override.ClassOverrideID == _orderClass && override.ClassOverrideMethod == methodName
    {
        resultSet.insert(override.RecId, override);
    }

    //Test if collector method has been passed, and find corresponding Post Method.
    methodName = TFMDocumentHandler::FindCorrespondingPostMethod(_orderClass,methodName);
    while select override where override.ClassOverrideID == _orderClass && override.ClassOverrideMethod == methodName
    {
        resultSet.insert(override.RecId, override);
    }


    return resultSet;
}

/// <summary>
/// Iterates through all the Post Prompt extensions that has been set up for the order, and executes the corresponding method.
/// </summary>
public static void FindAndExecute(Object _class, Map _returnAttributes, MethodName _classOverrideMethod = '')
{
    MobPostOrderPromptOverride override;
    while select override where override.Active && override.ClassOverrideID == classIdGet(_class) && (_classOverrideMethod == override.ClassOverrideMethod || !_classOverrideMethod)
    //while select override where override.ClassOverrideID == classIdGet(_class)
    {
        try
        {
            override.execute(_class,_returnAttributes);
        }
        catch(Exception::Error)
        {
            continue;
        }
    }
}

/// <summary>
///
/// </summary>
public void insert()
{
    super();
    //Add method Parameters
    this.addParms();



}

public void update()
{
    if (this.orig().callMethodName != this.CallMethodName)
    {
        //Add method Parameters
        this.addParms();
    }
    super();

}

private void execute(Object _class, Map _returnAttributes)
{
    MobPostOrderMethodParms             parms;
    MobPostOrderPromptOverrideLines     line;
    DictMethod                          method = new DictMethod(UtilElementType::ClassStaticMethod,className2Id(this.CallClassName),this.CallMethodName);
    Common                              resBuffer;
    container           parameters = conNull();
    int                 i;
    str                 strParmValue;
    Types               baseType;

    for (i = 1; i <= method.parameterCnt(); i++)
    {
        select firstonly parms where parms.PostOrderPromptOverrideRecID == this.RecId && parms.ParmName == method.parameterName(i);

        if (parms.ReturnTableName)
        {
            resBuffer = MobHelper::getBuffer(parms.ReturnTableName, _class);
        }

        if (parms.baseType == Types::Record)
        {
            parameters += resBuffer;
            continue;
        }

        if (parms.PostOrderPromptOverrideLinesRecId)
        {
            line = parms.Lines();
            strParmValue = _returnAttributes.lookup(line.Name);
        }

        if (parms.Expression)
        {
            strParmValue = TFMExpressions::evaluateExpression(parms.Expression,resBuffer,strParmValue);
        }
        baseType = method.parameterType(i);
        if (baseType == Types::UserType && method.parameterTypeName(i))
        {
            baseType = new DictType(extendedTypeName2Id(method.parameterTypeName(i))).baseType();
        }
        parameters += TFMDocCustomFunctionFlow::ConvertToType(strParmValue, baseType,method.parameterTypeName(i));

    }

    TFMDocCustomFunctionFlow::callMethodCon(this.CallClassName,this.CallMethodName, parameters);
}
